static int64_t fwp_u64_chars(uint64_t x) {
    int64_t n = 1;
    while (x >= 10) { x /= 10; n++; }
    return n;
}

static int64_t fwp_i64_chars(int64_t x) {
    return x < 0 ? 1 + fwp_u64_chars((uint64_t)0 - (uint64_t)x) : fwp_u64_chars((uint64_t)x);
}

